core.publicAPI:
TrainerCore/Health (all public, Sendable, Hashable; Codable unless noted):
- enum AerobicActivity: String, CaseIterable { walking, running, cycling, swimming, rowing, elliptical, hiking, stairs, hiit, dance, other; var displayName: String (pt-BR); var defaultIntensity: AerobicIntensity } (running/hiit/stairs = .vigorous, the rest = .moderate)
- enum AerobicIntensity: String, CaseIterable { light, moderate, vigorous }
- enum BiologicalSexValue: String, CaseIterable { female, male, other }
- struct AerobicWorkoutSample: Identifiable { let id: UUID; activity: AerobicActivity; start: Date; end: Date; minuteHeartRates: [Double]; init(id: UUID = UUID(), activity:, start:, end:, minuteHeartRates: [Double] = []) }
- struct DailyRecoverySample { let day: Date; hrvSDNN: Double?; restingHeartRate: Double?; sleepHours: Double?; init(day:, hrvSDNN: = nil, restingHeartRate: = nil, sleepHours: = nil) }
- struct DailyStepCount { let day: Date; steps: Int; init(day:steps:) }
- struct Vo2MaxSample { let date: Date; value: Double; init(date:value:) }
- struct UserPhysiology { let birthDate: Date?; sex: BiologicalSexValue?; maxHeartRateOverride: Int?; init(birthDate: = nil, sex: = nil, maxHeartRateOverride: = nil); func ageYears(at now: Date, calendar: Calendar) -> Int? }
- struct HealthInput { let physiology: UserPhysiology; aerobicWorkouts: [AerobicWorkoutSample]; recovery: [DailyRecoverySample]; steps: [DailyStepCount]; vo2Max: [Vo2MaxSample]; recentSessions: [SessionSummary]; init(physiology: = UserPhysiology(), aerobicWorkouts: = [], recovery: = [], steps: = [], vo2Max: = [], recentSessions: = []) }
- struct HealthTargets { let weeklyModerateEquivalentMinutes: Int; dailySteps: Int; sleepHours: Double; init(weeklyModerateEquivalentMinutes: Int = 150, dailySteps: Int = 7000, sleepHours: Double = 7) }
- struct HealthReport { let weekStart: Date; aerobic: AerobicWeekSummary; vo2Max: Vo2MaxSummary?; recovery: RecoverySummary; steps: StepsSummary; suggestions: [HealthSuggestion]; init(all fields) }
- struct AerobicWeekSummary { let moderateMinutes: Int; vigorousMinutes: Int; moderateEquivalentMinutes: Int; target: Int; perDay: [DailyAerobicMinutes] (always 7 entries, Mon..Sun); init(all fields) }
- struct DailyAerobicMinutes { let day: Date; moderate: Int; vigorous: Int; init(day:moderate:vigorous:) }
- struct Vo2MaxSummary { let latest: Double; latestDate: Date; change90Days: Double?; band: FitnessBand?; ageYears: Int?; init(all fields) }
- enum FitnessBand: String, CaseIterable { veryPoor, poor, fair, good, excellent, superior; var displayName: String } ("Muito baixo", "Baixo", "Regular", "Bom", "Excelente", "Superior")
- struct RecoverySummary { let hrv7, hrv28, restingHR7, restingHR28, sleep7, sleep28: Double?; nightsWithData7: Int; alerts: [RecoveryAlert]; init(all fields) }
- enum RecoveryAlert: String, CaseIterable { hrvDrop, restingHeartRateRise, lowSleep }
- struct StepsSummary { let average7: Int?; target: Int; init(average7:target:) }
- struct HealthSuggestion: Identifiable { let id: String; kind: HealthSuggestionKind; title: String; detail: String; referenceTopic: String; init(id:kind:title:detail:referenceTopic:) }
- enum HealthSuggestionKind: String, CaseIterable { wearWatchAtNight, updateVo2Max, aerobicDeficit, lowSleep, recoveryAlert, lowSteps }. Stable ids: "wear-watch-at-night", "update-vo2max", "aerobic-deficit", "low-sleep", "recovery-alert", "low-steps". Topics: topic.hrv, topic.vo2max, topic.aerobic, topic.sleep, topic.hrv, topic.steps.
- enum HealthCalculator: Sendable { static func report(input: HealthInput, targets: HealthTargets, now: Date, calendar: Calendar) -> HealthReport }
- struct HeartRateZones: Sendable, Hashable (not Codable) { static let moderateFractionOfMax = 0.64, vigorousFractionOfMax = 0.77, moderateFractionOfReserve = 0.40, vigorousFractionOfReserve = 0.60; let maxHeartRate: Double; let restingHeartRate: Double?; init(maxHeartRate: Double, restingHeartRate: Double? = nil); var usesHeartRateReserve: Bool; static func tanakaMaxHeartRate(ageYears: Int) -> Double; static func maxHeartRate(physiology: UserPhysiology, now: Date, calendar: Calendar) -> Double?; static func make(physiology: UserPhysiology, restingHeartRate: Double?, now: Date, calendar: Calendar) -> HeartRateZones?; func intensity(forHeartRate: Double) -> AerobicIntensity? }
- enum Vo2MaxNorms: Sendable { static let publishedPercentiles = [5, 10, 25, 50, 75, 90, 95]; static let coveredAges = 20...79; static func percentiles(ageYears: Int, sex: BiologicalSexValue) -> [Double]?; static func band(vo2Max: Double, ageYears: Int, sex: BiologicalSexValue) -> FitnessBand? }
Internal helpers (usable from T5.4 inside the same module): AerobicWeek, AerobicPlacement, RecoveryTrend, StepsTrend, Vo2MaxTrend, HealthSuggestions, HealthText, HealthDays, HealthMath.

reader.publicAPI:
// PersonalTrainer/Services/HealthKit/HealthDataReading.swift (app target, internal)
protocol HealthDataReading: Sendable {
    var isAvailable: Bool { get }
    func requestReadAuthorization() async throws
    func healthInput(now: Date, calendar: Calendar, recentSessions: [SessionSummary]) async throws -> HealthInput
}

// PersonalTrainer/Services/HealthKit/LiveHealthDataReader.swift
final class LiveHealthDataReader: HealthDataReading, @unchecked Sendable {
    static let lookbackDays = 28
    static let vo2MaxLookbackDays = 180
    static let nightCutoffShiftHours = 6
    let store: HKHealthStore            // = HKHealthStore()
    init()
    var isAvailable: Bool               // HKHealthStore.isHealthDataAvailable()
    func requestReadAuthorization() async throws
    func healthInput(now: Date, calendar: Calendar, recentSessions: [SessionSummary]) async throws -> HealthInput
    static func readTypes() -> Set<HKObjectType>
    static func aerobicActivity(for type: HKWorkoutActivityType) -> AerobicActivity?
    static func vo2MaxUnit() -> HKUnit
    static func isAsleep(categoryValue: Int) -> Bool
    static func isAppleWatch(productType: String?, deviceModel: String?) -> Bool
    static func birthDate(from components: DateComponents, timeZone: TimeZone) -> Date?
    static func biologicalSexValue(_ sex: HKBiologicalSex) -> BiologicalSexValue?
    // pure aggregation (extension)
    struct SleepSegment: Sendable, Hashable { let start: Date; let end: Date; let isFromWatch: Bool }
    static func nightDay(endingAt end: Date, calendar: Calendar) -> Date
    static func sleepHoursByDay(_ segments: [SleepSegment], calendar: Calendar) -> [Date: Double]
    static func unionDuration(of segments: [SleepSegment]) -> TimeInterval
    static func mergeRecovery(hrv: [Date: Double], restingHeartRate: [Date: Double], sleepHours: [Date: Double]) -> [DailyRecoverySample]
    static func dailySteps(from byDay: [Date: Double]) -> [DailyStepCount]
}

// PersonalTrainer/Services/HealthKit/FakeHealthDataReader.swift
final class FakeHealthDataReader: HealthDataReading {   // compiler-checked Sendable (only Sendable lets)
    let isAvailable: Bool
    init(input: HealthInput? = nil, isAvailable: Bool = true, authorizationError: HealthKitServiceError? = nil, readError: HealthKitServiceError? = nil)
    func requestReadAuthorization() async throws      // throws .unavailable if !isAvailable, else authorizationError if set
    func healthInput(now: Date, calendar: Calendar, recentSessions: [SessionSummary]) async throws -> HealthInput  // .unavailable / readError; otherwise input ?? sampleInput, always with recentSessions from the call
    static func sampleInput(now: Date, calendar: Calendar) -> HealthInput
}

