@Observable @MainActor final class HealthViewModel {
  enum Keys { static let readAuthorized = "healthReadAuthorized"; static let birthYear = "profileBirthYear"; static let sex = "profileSex"; static let maxHeartRate = "profileMaxHeartRate"; static let dismissedSuggestions = "healthDismissedSuggestions" }
  static let unavailableMessage: String   // "O app Saúde não está disponível neste aparelho."
  static let readFailedMessage: String
  static let authorizationFailedMessage: String
  static let maxHeartRateRange: ClosedRange<Int>   // 100...230
  static let vo2MaxWindowDays: Int                 // 90
  init(reader: any HealthDataReading, sessionsProvider: @escaping @MainActor () -> [SessionSummary], targets: HealthTargets = HealthTargets(), now: @escaping () -> Date, calendar: Calendar = .current, defaults: UserDefaults = .standard)
  private(set) var report: HealthReport?
  private(set) var isLoading: Bool
  var errorMessage: String?
  private(set) var needsAuthorization: Bool
  private(set) var isRequestingAuthorization: Bool
  private(set) var vo2MaxHistory: [Vo2MaxSample]
  private(set) var physiology: UserPhysiology?
  private(set) var healthProvidedPhysiology: UserPhysiology?
  private(set) var lastLoadedAt: Date?
  private(set) var profileBirthYear: Int?
  private(set) var profileSex: BiologicalSexValue?
  private(set) var profileMaxHeartRate: Int?
  let targets: HealthTargets
  let calendar: Calendar
  var isHealthAvailable: Bool { get }
  var visibleSuggestions: [HealthSuggestion] { get }
  var currentYear: Int { get }
  func load() async
  func loadIfStale(maxAge: TimeInterval = 15 * 60) async
  func requestAuthorization() async
  func saveProfile(birthYear: Int?, sex: BiologicalSexValue?, maxHeartRate: Int?)
  func dismiss(_ suggestion: HealthSuggestion)
}
